import os
import json

def initialize_progress_file(video_file):
    """Creates a progress file with initial 0 for the video file"""
    try:
        with open(video_file, 'x') as f:  # 'x' creates file only if it doesn't exist
            json.dump({"progress": 0}, f)
    except FileExistsError:
        pass  # File already exists

def get_progress(video_file):
    """Returns the current progress (0 = unwatched, 1 = watched)"""
    if not os.path.exists(video_file):
        initialize_progress_file(video_file)

    with open(video_file, 'r') as f:
        try:
            data = json.load(f)
            return data.get("progress", 0)
        except json.JSONDecodeError:
            # Fallback to previous format if JSON is invalid
            current_prog = int(open(video_file).read() or 0)
            with open(video_file, 'w') as f:
                json.dump({"progress": current_prog}, f)
            return current_prog

def increment_progress(video_file):
    """Increments progress from 0 to 1 (unwatched to watched)"""
    def _increment():
        current = get_progress(video_file)
        if current == 0:
            # Mark as watched by setting progress to 1
            data = {"progress": 1}
            with open(video_file, 'w') as f:
                json.dump(data, f)
            return True
        return False

    return _increment()

